// ===== DEALS SYNC CONFIG =====
const LOOKBACK_DAYS = 40;
const BACKFILL_START = '';   // '2020-01-01' once for full history, then ''

const DAY = 86400000; const now = Date.now();
let chunks = [];
if (BACKFILL_START) {
  let cur = Date.parse(BACKFILL_START);
  while (cur < now) { const d = new Date(cur); const nx = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1);
    chunks.push({ fromMs: cur, toMs: Math.min(nx, now) }); cur = nx; }
} else { chunks = [{ fromMs: now - LOOKBACK_DAYS * DAY, toMs: now }]; }

return chunks.map(c => ({ json: { fromMs: c.fromMs, toMs: c.toMs } }));

const ids = []; const seen = new Set();
for (const it of $input.all()) for (const r of (it.json.results || [])) if (!seen.has(r.id)) { seen.add(r.id); ids.push(r.id); }
const out = [];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { url: 'https://api.hubapi.com/crm/v4/associations/deals/companies/batch/read',
    body: { inputs: ids.slice(i, i + 100).map(id => ({ id })) } } });
if (!out.length) out.push({ json: { skip: true } });
return out;

const dealToCompanies = {};
for (const it of $('Read Assoc').all()) { if (it.json.skip) continue;
  for (const r of (it.json.results || []))
    dealToCompanies[String(r.from && r.from.id)] = (r.to || []).map(t => String(t.toObjectId)).filter(Boolean); }
const ids = [...new Set(Object.values(dealToCompanies).flat())];
const out = [{ json: { dealToCompanies } }];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { body: { inputs: ids.slice(i, i + 100).map(id => ({ id })), properties: ['name','lifecyclestage','type','hs_analytics_source','hs_analytics_source_data_1'] } } });
return out;

const esc = v => v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = v => v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v));
const bool = v => v ? 'true' : 'false';

const owners = {};
for (const o of ($('Get Owners').first().json.results || []))
  owners[String(o.id)] = ((o.firstName || '') + ' ' + (o.lastName || '')).trim() || o.email || String(o.id);

const state = $('Build Company Reads').all()[0].json;
const comps = {};
for (const it of $('Read Companies').all()) for (const r of ((it.json || {}).results || [])) {
  const p = r.properties || {};
  comps[String(r.id)] = { name: p.name || '',
    isPartner: /partner|agentur|agency/i.test(String(p.lifecyclestage || '') + ' ' + String(p.type || '')),
    srcType: p.hs_analytics_source || null, srcDetail: p.hs_analytics_source_data_1 ? String(p.hs_analytics_source_data_1).slice(0, 80) : null };
}
const dtLabels = {};
for (const o of (($('Get Dealtypes').first().json || {}).options || [])) dtLabels[o.value] = o.label;
const hasQuote = new Set();
for (const it of $('Read Quotes Assoc').all()) for (const r of ((it.json || {}).results || []))
  if ((r.to || []).length) hasQuote.add(String(r.from && r.from.id));
const ai = {};
for (const it of $input.all()) {
  const content = it.json && it.json.content;
  if (!Array.isArray(content)) continue;
  let t = content.filter(c => c.type === 'text').map(c => c.text).join('');
  try { for (const r of JSON.parse(t.replace(/```json|```/g, '').trim())) ai[String(r.id)] = r; } catch (e) {}
}
const pipes = {}; const stages = {};
for (const p of ($('Get Pipelines').first().json.results || [])) {
  pipes[p.id] = p.label;
  for (const s of (p.stages || [])) stages[s.id] = s.label;
}
const rows = []; const seen = new Set();
for (const it of $('Search Deals').all()) for (const d of (it.json.results || [])) {
  if (seen.has(d.id)) continue; seen.add(d.id);
  const p = d.properties || {};
  const assocIds = state.dealToCompanies[String(d.id)] || [];
  const primaryId = assocIds.find(id => comps[id] && !comps[id].isPartner) || assocIds[0] || null;
  const partnerId = assocIds.find(id => comps[id] && comps[id].isPartner) || null;
  const comp = primaryId;
  const partnerName = partnerId && comps[partnerId] ? comps[partnerId].name : null;
  rows.push('(' + [num(d.id), esc(p.dealname), num(comp), esc(comp && comps[comp] ? comps[comp].name : ''),
    esc(pipes[p.pipeline] || p.pipeline), esc(stages[p.dealstage] || p.dealstage), num(p.amount),
    esc(owners[String(p.hubspot_owner_id)] || 'Unknown'),
    esc(p.createdate ? p.createdate.slice(0, 10) : null), esc(p.closedate ? p.closedate.slice(0, 10) : null),
    esc(p.dealtype ? (dtLabels[p.dealtype] || p.dealtype) : 'Unknown'), bool(String(p.hs_is_closed) === 'true'), bool(String(p.hs_is_closed_won) === 'true'),
    esc(p.hs_next_step ? String(p.hs_next_step).slice(0, 200) : null),
    esc(p.notes_last_updated ? String(p.notes_last_updated).slice(0, 10) : null),
    num(p.hs_mrr), bool(hasQuote.has(String(d.id))), esc(partnerName),
    esc(comp && comps[comp] ? comps[comp].srcType : null), esc(comp && comps[comp] ? comps[comp].srcDetail : null),
    esc(p.license_start_date__c ? String(p.license_start_date__c).slice(0, 10) : (p.contract_signed_on__c ? String(p.contract_signed_on__c).slice(0, 10) : null)),
    esc((ai[String(d.id)] || {}).status || null), esc((ai[String(d.id)] || {}).todo || null),
    esc(new Date().toISOString())].join(',') + ')');
}
if (!rows.length) return [{ json: { sql: 'SELECT 1;' } }];
return [{ json: { sql: 'INSERT INTO deals_mirror (deal_id,deal_name,company_id,company_name,pipeline_label,stage_label,amount,owner_name,create_date,close_date,dealtype,is_closed,is_won,next_step,last_activity,mrr,has_quote,partner_name,source_type,source_detail,license_start,status_note,todo,updated_at) VALUES\n' +
  rows.join(',\n') + '\nON CONFLICT (deal_id) DO UPDATE SET deal_name=EXCLUDED.deal_name, company_id=EXCLUDED.company_id, company_name=EXCLUDED.company_name, pipeline_label=EXCLUDED.pipeline_label, stage_label=EXCLUDED.stage_label, amount=EXCLUDED.amount, owner_name=EXCLUDED.owner_name, create_date=EXCLUDED.create_date, close_date=EXCLUDED.close_date, dealtype=EXCLUDED.dealtype, is_closed=EXCLUDED.is_closed, is_won=EXCLUDED.is_won, next_step=EXCLUDED.next_step, last_activity=EXCLUDED.last_activity, mrr=EXCLUDED.mrr, has_quote=EXCLUDED.has_quote, partner_name=EXCLUDED.partner_name, source_type=EXCLUDED.source_type, source_detail=EXCLUDED.source_detail, license_start=EXCLUDED.license_start, status_note=COALESCE(EXCLUDED.status_note, deals_mirror.status_note), todo=EXCLUDED.todo, updated_at=EXCLUDED.updated_at;' } }];

const ids = []; const seen = new Set();
for (const it of $('Search Deals').all()) for (const r of (it.json.results || [])) if (!seen.has(r.id)) { seen.add(r.id); ids.push(r.id); }
const out = [];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { body: { inputs: ids.slice(i, i + 100).map(id => ({ id })) } } });
if (!out.length) out.push({ json: { skip: true } });
return out;

const quotes = new Set();
for (const it of $('Read Quotes Assoc').all()) for (const r of ((it.json || {}).results || []))
  if ((r.to || []).length) quotes.add(String(r.from && r.from.id));
const seen = new Set(); const items = [];
const now = Date.now();
for (const it of $('Search Deals').all()) for (const d of (it.json.results || [])) {
  if (seen.has(d.id)) continue; seen.add(d.id);
  const p = d.properties || {};
  if (String(p.hs_is_closed) === 'true') continue;
  const la = p.notes_last_updated ? Math.round((now - Date.parse(p.notes_last_updated)) / 86400000) : null;
  const age = p.createdate ? Math.round((now - Date.parse(p.createdate)) / 86400000) : null;
  items.push({ id: d.id, name: String(p.dealname || '').slice(0, 80), stage: p.dealstage, type: p.dealtype || '',
    age_days: age, days_since_activity: la, next_step: String(p.hs_next_step || '').slice(0, 200) });
}
if (!items.length) return [{ json: { has: false, quotes: [...quotes] } }];
const out = [];
for (let i = 0; i < items.length; i += 20) {
  out.push({ json: { has: true, quotes: [...quotes], body: { model: 'claude-sonnet-5', max_tokens: 2200, messages: [{ role: 'user', content:
    'You write one-glance pipeline notes for a B2B sales dashboard (JENTIS). For each OPEN deal, from its next_step text and activity facts, produce: ' +
    'status (max 7 words, qualitative, what is happening / where it stands, e.g. "Quote sent, waiting on prospect" or "Fresh deal, discovery done") and ' +
    'todo (max 6 words, the concrete action on our side, or null). If next_step is empty, derive from staleness (e.g. "No activity 24d - re-engage"). German next_steps may be answered in English. ' +
    'Respond ONLY with a JSON array, no fences: [{"id":"...","status":"...","todo":...}]\n\n' + JSON.stringify(items.slice(i, i + 20)) } ] } } });
}
return out;
